solution:
type Action =
  | { type: "ajouter"; produit: string }
  | { type: "retirer"; produit: string }
  | { type: "vider" };

function appliquer(panier: string[], action: Action): string[] {
  switch (action.type) {
    case "ajouter":
      return [...panier, action.produit];
    case "retirer": {
      const i = panier.indexOf(action.produit);
      return i === -1 ? [...panier] : [...panier.slice(0, i), ...panier.slice(i + 1)];
    }
    case "vider":
      return [];
    default: {
      const impossible: never = action;
      return impossible;
    }
  }
}
